window.RTLBenchLSData.register("assets/d3b3684528bd0d6bbace497b560da5afd19e78676f480ac4d37007e70aa2b61d.txt","`default_nettype none\n`timescale 1ns/1ns\n\n// INSTRUCTION DECODER\n// > Decodes an instruction into the control signals necessary to execute it\n// > Each core has it's own decoder\nmodule decoder (\n    input wire clk,\n    input wire reset,\n\n    input reg [2:0] core_state,\n    input reg [15:0] instruction,\n    \n    \n    output reg [3:0] decoded_rd_address,\n    output reg [3:0] decoded_rs_address,\n    output reg [3:0] decoded_rt_address,\n    output reg [2:0] decoded_nzp,\n    output reg [7:0] decoded_immediate,\n    \n    \n    output reg decoded_reg_write_enable,           \n    output reg decoded_mem_read_enable,            \n    output reg decoded_mem_write_enable,           \n    output reg decoded_nzp_write_enable,           \n    output reg [1:0] decoded_reg_input_mux,        \n    output reg [1:0] decoded_alu_arithmetic_mux,   \n    output reg decoded_alu_output_mux,             \n    output reg decoded_pc_mux,                     \n\n    \n    output reg decoded_ret\n);\nendmodule\n");
